import jwt

logger = logging.getLogger('auth.events')
SIGNING_KEY = 'internal-session-key'
ALGORITHM = 'HS256'


class SessionIssuer:
    def __init__(self, signing_key=SIGNING_KEY):
        self.signing_key = signing_key

    def claims_for(self, customer):
        return {
            'sub': str(customer.id),
            'email': customer.email,
            'rut': customer.rut,
            'scope': 'customer',
        }

    def issue(self, customer):
        claims = self.claims_for(customer)
        token = jwt.encode(claims, self.signing_key, algorithm=ALGORITHM)
        logger.info('issued session for claims %s', claims)
        return {'token': token, 'expires_in': 3600}


def handle_login(customer):
    return SessionIssuer().issue(customer)

