ARCHIVE_NOTE = 'invoices before {cutoff} archived, retention={days}d'


class ArchivableMixin:
    RETENTION_DAYS = TAX_RETENTION_DAYS

    def cutoff(self):
        return datetime.utcnow() - timedelta(days=self.RETENTION_DAYS)

    def note(self):
        return ARCHIVE_NOTE.format_map({
            'cutoff': self.cutoff().date().isoformat(),
            'days': self.RETENTION_DAYS,
        })


class InvoiceArchiveJob(ArchivableMixin):
    def run(self):
        cutoff = self.cutoff()
        updated = (
            Invoice.objects.filter(issued_at__lt=cutoff, archived=False)
            .update(archived=True)
        )
        return {'archived': updated, 'note': self.note()}

