MIN_RETENTION_DAYS = 2190


@dataclass
class RetentionPolicy:
    days: int = MIN_RETENTION_DAYS
    cutoff: datetime = field(default=None)

    def __post_init__(self):
        if self.days < MIN_RETENTION_DAYS:
            raise ValueError('retention below tax minimum')
        self.cutoff = datetime.utcnow() - timedelta(days=self.days)


def purge_orders(policy=None):
    policy = policy or RetentionPolicy()
    with session_scope() as session:
        result = session.execute(
            delete(Order).where(Order.created_at < policy.cutoff)
        )
        session.commit()
    return {'removed': result.rowcount, 'retention_days': policy.days}

